"""The app's .env (spec 021): loaded at start, never replacing a variable the process has."""

from __future__ import annotations

import os
from pathlib import Path

import pytest

from synapsis.config import env, load_env_file


def test_the_env_file_fills_only_what_the_process_lacks(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    f = tmp_path / ".env"
    f.write_text(
        '# Generated by NuclearLang\nSYN_PLAIN=tasks.sqlite\nSYN_QUOTED="two\\nlines \\"q\\" \\\\ \\$HOME"\nSYN_KEPT=from-file\n',
        encoding="utf-8",
    )
    monkeypatch.setenv("SYN_KEPT", "from-process")
    for name in ("SYN_PLAIN", "SYN_QUOTED"):
        monkeypatch.delenv(name, raising=False)
    load_env_file(str(f))
    try:
        assert env("SYN_PLAIN") == "tasks.sqlite"
        assert env("SYN_QUOTED") == 'two\nlines "q" \\ $HOME'
        assert env("SYN_KEPT") == "from-process"
        assert env("SYN_NONE", "default") == "default"
    finally:
        for name in ("SYN_PLAIN", "SYN_QUOTED"):
            os.environ.pop(name, None)


def test_no_env_file_changes_nothing(tmp_path: Path) -> None:
    before = dict(os.environ)
    load_env_file(str(tmp_path / ".env"))
    assert dict(os.environ) == before
